import{_ as t,o,c as d,a3 as c}from"./chunks/framework.BTQ4eCVb.js";const h=JSON.parse('{"title":"Products — Developer Guide","description":"","frontmatter":{"head":[["meta",{"property":"og:title","content":"Products — Developer Guide | EloSync Docs"}],["meta",{"property":"og:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"property":"og:url","content":"https://docs.elosync.com/developer-guide/products"}],["meta",{"property":"og:image","content":"https://docs.elosync.com/og-image.svg"}],["meta",{"name":"twitter:card","content":"summary_large_image"}],["meta",{"name":"twitter:title","content":"Products — Developer Guide | EloSync Docs"}],["meta",{"name":"twitter:description","content":"Official documentation for the EloSync SaaS Platform."}],["meta",{"name":"twitter:image","content":"https://docs.elosync.com/og-image.svg"}],["link",{"rel":"canonical","href":"https://docs.elosync.com/developer-guide/products"}]]},"headers":[],"relativePath":"developer-guide/products.md","filePath":"developer-guide/products.md","lastUpdated":1788459257000}'),a={name:"developer-guide/products.md"};function i(s,e,r,n,l,p){return o(),d("div",null,[...e[0]||(e[0]=[c(`<h1 id="products-—-developer-guide" tabindex="-1">Products — Developer Guide <a class="header-anchor" href="#products-—-developer-guide" aria-label="Permalink to &quot;Products — Developer Guide&quot;">​</a></h1><p>Products is the Phase 5 catalog module. It follows the Leads-style module layout: tenant model, form requests, resources, policy, service, events/subscriber, activity logging, frontend list/form/detail UI, and Playwright coverage.</p><h2 id="backend" tabindex="-1">Backend <a class="header-anchor" href="#backend" aria-label="Permalink to &quot;Backend&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Piece</th><th>Path</th></tr></thead><tbody><tr><td>Models</td><td><code>Product</code>, <code>ProductCategory</code>, <code>ProductNote</code>, <code>ProductActivity</code></td></tr><tr><td>Service</td><td><code>app/Services/Tenant/ProductService.php</code></td></tr><tr><td>HTTP</td><td><code>ProductController</code>, <code>ProductCategoryController</code>, <code>app/Http/Requests/Tenant/Api/V1/Product*</code></td></tr><tr><td>Resources</td><td><code>app/Http/Resources/Tenant/Api/V1/Product*</code></td></tr><tr><td>Authorization</td><td><code>ProductPolicy</code>, <code>ProductCategoryPolicy</code></td></tr><tr><td>Tests</td><td><code>tests/Feature/Tenant/Product/</code></td></tr></tbody></table><p>Products is gated by <code>module:products</code> and <code>products.view|create|update|delete|restore|force.delete</code>. Category CRUD uses the same permissions.</p><h2 id="domain-rules" tabindex="-1">Domain rules <a class="header-anchor" href="#domain-rules" aria-label="Permalink to &quot;Domain rules&quot;">​</a></h2><ul><li><code>sku</code> is unique per tenant; category is nullable and is nullified if removed.</li><li>On create, <code>sku</code> may be omitted or blank — <code>ProductService</code> assigns the next SKU (<code>products_sku_prefix</code> tenant setting, default <code>SKU-</code>, plus a 5-digit sequence including soft-deleted rows) and retries on unique collisions. Clients may override with an explicit SKU. <code>GET /products/next-sku</code> previews the next value for the SPA.</li><li>Product <code>description</code> accepts sanitized HTML (same allowlist as billing document notes; <code>style</code> stripped, <code>javascript:</code> / <code>data:</code> hrefs neutralized); empty HTML is stored as <code>null</code>.</li><li>There is no separate product/service type. Services are catalog rows with <code>track_stock = false</code>.</li><li><code>track_stock</code> controls whether <code>StockService</code> can mutate a product&#39;s stock.</li><li>Product notes and <code>product_activities</code> provide the domain timeline; the model also uses Spatie <code>LogsActivity</code>.</li><li><code>product_id</code> on <code>purchase_order_lines</code> and billing document lines (<code>quotation_lines</code>, <code>estimate_lines</code>, <code>customer_invoice_lines</code>) is nullable and validated by <code>LinkableProduct</code> when supplied: Products module entitled, actor has <code>products.view</code> (or superadmin), product is active and not soft-deleted, same tenant.</li><li>Billing SPA line pickers (and purchase-order picker) gate on Products + <code>products.view</code>, list <strong>active</strong> products with server search, auto-fill line text on select, and leave edited fields intact when clearing the link. Convert estimate → invoice and recurring invoice generation copy <code>product_id</code>.</li></ul><p>Catalog: slug <code>products</code>, version <strong>1.2.0</strong> (auto SKU + HTML description + link hardening).</p><h2 id="frontend-and-verification" tabindex="-1">Frontend and verification <a class="header-anchor" href="#frontend-and-verification" aria-label="Permalink to &quot;Frontend and verification&quot;">​</a></h2><p>Pages are in <code>src/pages/products/</code> (<code>products-page.tsx</code>, <code>product-form.tsx</code> + <code>product-form-page.tsx</code>, <code>product-view-page.tsx</code>). Category CRUD stays in <code>product-categories-dialog.tsx</code>. Service/types/query keys/permissions live in the shared API, type, constants, and navigation layers. The route and nav item use <code>module:products</code> plus <code>products.view</code>. Currency uses shared <code>currencyOptions()</code> / <code>SearchableSelect</code> and defaults to tenant <code>settings.currency</code> on create.</p><p>Run:</p><div class="language-bash vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">bash</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">php</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> artisan</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> --compact</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> tests/Feature/Tenant/Product</span></span>
<span class="line"><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">npm</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> run</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;"> test:e2e:products</span></span></code></pre></div>`,12)])])}const m=t(a,[["render",i]]);export{h as __pageData,m as default};
